import{_ as n}from"./chunks/Audio.COine8Wh.js";import{c as t,o as a,j as i,G as r,ae as l,a as s}from"./chunks/framework.Bw0Gm4PQ.js";const d=JSON.parse('{"title":"Unleashing American Energy","description":"","frontmatter":{"legisId":"2025-01-21-unleashing-american-energy","title":"Unleashing American Energy","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/01/unleashing-american-energy/","publishDate":"2025-01-20T20:34:55-05:00","head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Executive Orders\\",\\"item\\":\\"https://vladroff.github.io/legis/executive-orders\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Unleashing American Energy\\",\\"item\\":\\"https://vladroff.github.io/legis/executive-orders/2025-01-21-unleashing-american-energy\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Unleashing American Energy\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/executive-orders/2025-01-21-unleashing-american-energy\\",\\"datePublished\\":\\"2025-01-20T20:34:55-05:00\\",\\"dateModified\\":1788575397000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/executive-orders/2025-01-21-unleashing-american-energy\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"executive-orders/2025-01-21-unleashing-american-energy.md","filePath":"executive-orders/2025-01-21-unleashing-american-energy.md","lastUpdated":1788575397000}'),o={name:"executive-orders/2025-01-21-unleashing-american-energy.md"},m=Object.assign(o,{setup(c){return(g,e)=>(a(),t("div",null,[e[0]||(e[0]=i("h1",{id:"unleashing-american-energy",tabindex:"-1"},[s("Unleashing American Energy "),i("a",{class:"header-anchor",href:"#unleashing-american-energy","aria-label":'Permalink to "Unleashing American Energy"'},"​")],-1)),r(n),e[1]||(e[1]=l('<p>Published on Tuesday, January 21, 2025</p><ul><li><p><strong>Background</strong></p><ul><li>America has abundant energy and resources crucial for economic prosperity.</li><li>Regulations have hindered resource development, increased energy costs, and affected national security.</li><li>The goal is to enable affordable energy to bolster American prosperity and security.</li></ul></li><li><p><strong>Policy Objectives</strong></p><ul><li>Encourage energy exploration on Federal lands and waters.</li><li>Establish the U.S. as a leader in non-fuel mineral production.</li><li>Ensure reliable energy access for economic and national security.</li><li>Base all energy regulations on applicable law.</li><li>Eliminate electric vehicle mandates to promote consumer choice.</li><li>Protect the ability to choose various appliances and enhance market competition.</li><li>Separate global impacts from domestic costs in regulatory evaluations.</li><li>Ensure public comment and scientific analysis in agency actions.</li><li>Prevent Federal funding contrary to the outlined principles.</li></ul></li><li><p><strong>Immediate Review of Agency Actions</strong></p><ul><li>Agencies must review regulations that burden domestic energy development and take corrective actions within 30 days.</li><li>Notify the Attorney General regarding adjustments to agency actions.</li></ul></li><li><p><strong>Revocations and Revisions</strong></p><ul><li>Revocation of specific previous executive orders related to climate and environmental regulations.</li><li>Termination of the American Climate Corps and related programs.</li><li>Reallocation of resources from abolished programs.</li></ul></li><li><p><strong>Efficient Permitting</strong></p><ul><li>Revocation of past environmental protection orders.</li><li>CEQ to provide guidance for expedited permitting processes.</li><li>Agencies to eliminate permitting delays and prioritize key projects.</li></ul></li><li><p><strong>Environmental Analysis Accuracy</strong></p><ul><li>Agencies to adhere strictly to legal environmental requirements.</li><li>Disbanding of the Interagency Working Group on Social Cost of Greenhouse Gases.</li><li>Review and potential elimination of the social cost of carbon in regulations.</li></ul></li><li><p><strong>Termination of the Green New Deal</strong></p><ul><li>Pause on fund disbursement related to specific infrastructure acts until review for compliance with new policies.</li><li>Agencies to prioritize cost-effectiveness and American jobs in funding decisions.</li></ul></li><li><p><strong>National Security Measures</strong></p><ul><li>Restart reviews on approvals for liquified natural gas export projects.</li><li>Assess refining proposals for potential adverse environmental impacts.</li></ul></li><li><p><strong>Restoring Mineral Dominance</strong></p><ul><li>Identify and revise burdens on domestic mining and processing.</li><li>Enhance efforts to find new critical mineral deposits.</li><li>Assess implications of global mineral reliance and forced labor issues.</li></ul></li><li><p><strong>General Provisions</strong></p><ul><li>The order does not impair legal authorities or rights.</li><li>Implementation is subject to applicable law and budget availability.</li><li>No rights or benefits are created for any party against the U.S. or its entities.</li></ul></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/01/unleashing-american-energy/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/01/unleashing-american-energy/</a></p>',3))]))}});export{d as __pageData,m as default};
